import assets from './assets.js';import {boardProxy} from './board-proxy.js';export default {async fetch(request){const url=new URL(request.url);if(url.pathname==='/api/board')return boardProxy(request);if(!['GET','HEAD'].includes(request.method))return new Response('Method not allowed',{status:405});const route=url.pathname;if(!route.endsWith('/')&&assets[route+'/'])return Response.redirect(url.origin+route+'/'+url.search,308);const asset=assets[route];if(!asset)return new Response('Page not found',{status:404});const bytes=Uint8Array.from(atob(asset.body),c=>c.charCodeAt(0));return new Response(request.method==='HEAD'?null:bytes,{headers:{'Content-Type':asset.type,'Cache-Control':asset.type.startsWith('text/html')?'no-cache':'public, max-age=3600','X-Content-Type-Options':'nosniff','Referrer-Policy':'strict-origin-when-cross-origin'}});}};